CREATE POLICY "Owner reads career vision images" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='career-vision' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'candidate')); CREATE POLICY "Owner uploads career vision images" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='career-vision' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'candidate')); CREATE POLICY "Owner removes career vision images" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='career-vision' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'candidate'));